/** All of the different padding size options. */
export declare const paddingOptions: {
    0: string;
    2: string;
    4: string;
    6: string;
    8: string;
    12: string;
    16: string;
    20: string;
    24: string;
    32: string;
    48: string;
    56: string;
    64: string;
};
/** Simple padding option. All paddings are set to the given size. */
export type PaddingSimpleOptionsType = keyof typeof paddingOptions;
/** Detailed padding option. All paddings can be configured individually. */
export interface PaddingDetailOptionsType {
    /** @defaultValue 0 */
    top?: PaddingSimpleOptionsType;
    /** @defaultValue 0 */
    bottom?: PaddingSimpleOptionsType;
    /** @defaultValue 0 */
    left?: PaddingSimpleOptionsType;
    /** @defaultValue 0 */
    right?: PaddingSimpleOptionsType;
}
/**
 * Shorthand syntax for defining the paddings.
 * Options:
 * [top/bottom/left/right], egg. ["Size16"]
 * [top/bottom, left/right], egg. ["Size8", "Size16"]
 * [top, right/left/ bottom], egg. ["Size24", "Size16", "Size8"]
 * [top, right, bottom, left], egg. ["Size16", "Size8", "Size4", "Size24"]
 */
export type PaddingShortHandSyntax = [PaddingSimpleOptionsType] | [PaddingSimpleOptionsType, PaddingSimpleOptionsType] | [
    PaddingSimpleOptionsType,
    PaddingSimpleOptionsType,
    PaddingSimpleOptionsType
] | [
    PaddingSimpleOptionsType,
    PaddingSimpleOptionsType,
    PaddingSimpleOptionsType,
    PaddingSimpleOptionsType
];
